ee:message.ee:set-payload:
%dw 2.0
output application/json
fun t(x) = {"type": typeOf(x) as String, "class": x.^class default null}
---
payload map (r) -> {
  Name: r.Name, Amount__c: r.Amount__c, Due__c: r.Due__c, Sync_Deleting__c: r.Sync_Deleting__c,
  Sync_Version__c: r.Sync_Version__c, Status__c: r.Status__c,
  types: {Name: t(r.Name), Amount__c: t(r.Amount__c), Due__c: t(r.Due__c), Sync_Deleting__c: t(r.Sync_Deleting__c),
          Sync_Version__c: t(r.Sync_Version__c), CreatedDate: t(r.CreatedDate)}
}
